	"Customer": "SELECT icustomerid, vcexternalcustid, vccustomername, vccustomertype, vcsalutation, vcverifiedname, vcgender, dtdoidob, dtonboardingdate, vcpostalcode, vcemail, vcregisteredmobile, imcc, vcidentitytype1, vcidentitydetails1, vcidentitytype2, vcidentitydetails2, vcregisteredaddressgeolocation, iadm3, iadm2, iadm1, vccountrycode, vcattribs->''yb_raw''->>''pan'' as \"PAN\", vcattribs->''yb_raw''->>''city'' as \"City\", vcattribs->''yb_raw''->>''gstn'' as \"GSTN\", vcattribs->''yb_raw''->>''state'' as \"State\", vcattribs->''yb_raw''->>''pinCode'' as \"Pin Code\", vcattribs->''yb_raw''->>''district'' as \"District\", vcattribs->''yb_raw''->>''latitude'' as \"Latitude\", vcattribs->''yb_raw''->>''longitude'' as \"Longitude\", vcattribs->''yb_raw''->>''partnerName'' as \"Partner Name\", vcattribs->''yb_raw''->>''businessName'' as \"Business Name\", vcattribs->''yb_raw''->>''mobileNumber'' as \"Mobile No.\", vcattribs->''yb_raw''->>''sellerVerifiedAccountName'' as \"Verified Acc. Name\", vcattribs->''yb_raw''->>''turnOverType'' as \"Turnover Type\", irecordstatus, dtentrydatetime FROM masters.customers :AttribsForm order by icustomerid desc limit 50000;"
}'::TEXT, formattingrequiered=false WHERE idashboardqueryid=48;

